require "config.php";$ids=$_POST["ids"]??[];if(!$ids)die("No seleccionó personas.");$plantilla=__DIR__."/plantilla/certificado.jpg";$fuente=__DIR__."/fonts/DejaVuSans.ttf";$dir=__DIR__."/certificados";if(!is_dir($dir))mkdir($dir,0775,true);$ok=0;$links=[];foreach($ids as $id){$id=(int)$id;$r=$conexion->query("SELECT * FROM certificados WHERE id=$id");if(!$r||!$r->num_rows)continue;$c=$r->fetch_assoc();$im=imagecreatefromjpeg($plantilla);$col=imagecolorallocate($im,20,20,20);$txt=mb_strtoupper($c["nombre"]." ".$c["apellido"],"UTF-8");$tam=32;$b=imagettfbbox($tam,0,$fuente,$txt);$x=(imagesx($im)-($b[2]-$b[0]))/2;imagettftext($im,$tam,0,$x,500,$col,$fuente,$txt);$url="https://localhost/sistema_certificados_v7_correo/verificar.php?codigo=".urlencode($c["codigo"]);$q=@imagecreatefrompng("https://api.qrserver.com/v1/create-qr-code/?size=220x220&data=".urlencode($url));if($q){$q=imagescale($q,150,150);imagecopy($im,$q,60,875,0,0,150,150);imagedestroy($q);}$f="certificado_".$c["codigo"].".jpg";imagejpeg($im,$dir."/".$f,95);imagedestroy($im);$s=$conexion->prepare("UPDATE certificados SET archivo=? WHERE id=?");$s->bind_param("si",$f,$id);$s->execute();$links[]=$f;$ok++;}?><!doctype html><html lang="es"><head><meta charset="utf-8"><title>Generación masiva</title><style>body{font-family:Arial;background:#eee;padding:30px}.box{max-width:800px;margin:auto;background:white;padding:30px;border-radius:12px}a{display:inline-block;margin:5px;padding:10px;background:#9b741c;color:white;text-decoration:none;border-radius:5px}</style></head><body><div class="box"><h2>Generación terminada</h2><p>Generados: <b><?=$ok?></b></p><?php foreach($links as $f):?><p><a href="certificados/<?=urlencode($f)?>" download><?=htmlspecialchars($f)?></a></p><?php endforeach;?><a href="listado.php">VOLVER AL LISTADO</a></div></body></html>